import React, { useState, useEffect } from 'react';
import './UserText.css';
import { Link } from 'react-router-dom';

const UserText = () => {
  const [text, setText] = useState('');
  const [status, setStatus] = useState('');
  const [ws, setWs] = useState(null);

  useEffect(() => {
    const websocket = new WebSocket('ws://localhost:8081');
    websocket.onopen = () => console.log('Connected to text');
    websocket.onmessage = (event) => console.log('Got:', event.data);
    websocket.onerror = (error) => console.error('Problem:', error);
    setWs(websocket);

    return () => websocket.close();
  }, []);

  const handleClick = (char) => {
    setText(prev => prev + char);
  };

  const handleSubmit = () => {
    if (!text) {
      setStatus('Please enter some text before submitting.');
      return;
    }

    if (ws && ws.readyState === WebSocket.OPEN) {
      ws.send(text);
      setStatus(`Submitted: "${text}" successfully.`);
      setText('');
    } else {
      setStatus('WebSocket not connected.');
    }
  };

  const handleReset = () => {
    setText('');
    setStatus('');
  };

  const uppercase = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('');
  const numbers = '0123456789'.split('');

  return (
    <div className="section4-wrapper">
      <div className="text-display">{text || 'Text'}</div>

      <div className="button-group">
        <button className="action-button" onClick={handleSubmit}>Submit</button>
        <button className="action-button" onClick={handleReset}>Reset</button>
      </div>

      {status && <div className="status-message">{status}</div>}

      <div className="keyboard-container">
        <div className="keyboard-grid">
          {uppercase.map(char => (
            <button key={char} className="letter-button" onClick={() => handleClick(char)}>
              {char}
            </button>
          ))}
        </div>

        <div className="keyboard-grid">
          {numbers.map(num => (
            <button key={num} className="letter-button" onClick={() => handleClick(num)}>
              {num}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
};

export default UserText;
